import sys,re
sys.path.insert(0,'/tmp/probe')
import sep2 as sep
ANSI=re.compile(rb'\x1b\[[0-9;]*m')
def classify(o):
    out=[]
    for l in o.split(b'\r\n'):
        s=ANSI.sub(b'',l).replace(b'\x00',b'').replace(b'\n',b'').decode('utf8','replace')
        if not s: out.append('.'); continue
        c=s[0]
        if c=='┌': out.append('T')
        elif c=='├': out.append('-')
        elif c=='└': out.append('B')
        elif c=='│':
            body=s[1:].split('│')[0].strip()
            out.append(body[:6] if body else '~')
        else: out.append('?'+s[:6])
    return out
for r in range(1,26):
    o,e,rc=sep.run(('-k',),cols=80,rows=r,keys=[b'q'],wait=0.35,final_wait=0.15)
    print('rows=%2d  %s'%(r,' '.join(classify(o))))
